export type CustomerInvoicesEInvoicesImportsImportOptionsInvoiceLine = {
  /**
   * Factur-X line identifier (BT-126 LineID).
   */
  e_invoice_line_id: string;
  /**
   * Ledger account id for this line.
   */
  ledger_account_id?: number | null;
  /**
   * Product id for this line.
   */
  product_id?: number | null;
};

/**
 * Optional JSON payload to enrich the imported customer invoice.
 * Invoice line `e_invoice_line_id` must match Factur-X BT-126 (LineID).
 *
 */
export type CustomerInvoicesEInvoicesImportsImportOptions = {
  /**
   * Customer id for the imported invoice.
   */
  customer_id?: number;
  invoice_lines?: Array<{
    /**
     * Factur-X line identifier (BT-126 LineID).
     */
    e_invoice_line_id: string;
    /**
     * Ledger account id for this line.
     */
    ledger_account_id?: number | null;
    /**
     * Product id for this line.
     */
    product_id?: number | null;
  }>;
};

export const BillingSubscriptionStatus = {
  DRAFT: 'draft',
  STOPPED: 'stopped',
  FINISHED: 'finished',
  PENDING: 'pending',
  NOT_STARTED: 'not_started',
  IN_PROGRESS: 'in_progress',
} as const;

export type BillingSubscriptionStatus =
  (typeof BillingSubscriptionStatus)[keyof typeof BillingSubscriptionStatus];

/**
 * - `awaiting_validation`: generated invoices will be in draft
 * - `finalized`: generated invoices will be finalized
 * - `email`: generated invoices will be finalized and sent by email to the recipients configured on the subscription
 *
 */
export const BillingSubscriptionMode = {
  AWAITING_VALIDATION: 'awaiting_validation',
  FINALIZED: 'finalized',
  EMAIL: 'email',
} as const;

/**
 * - `awaiting_validation`: generated invoices will be in draft
 * - `finalized`: generated invoices will be finalized
 * - `email`: generated invoices will be finalized and sent by email to the recipients configured on the subscription
 *
 */
export type BillingSubscriptionMode =
  (typeof BillingSubscriptionMode)[keyof typeof BillingSubscriptionMode];

export const BillingSubscriptionPaymentConditions = {
  UPON_RECEIPT: 'upon_receipt',
  '7_DAYS': '7_days',
  '15_DAYS': '15_days',
  '30_DAYS': '30_days',
  '30_DAYS_END_OF_MONTH': '30_days_end_of_month',
  '45_DAYS': '45_days',
  '45_DAYS_END_OF_MONTH': '45_days_end_of_month',
  '60_DAYS': '60_days',
} as const;

export type BillingSubscriptionPaymentConditions =
  (typeof BillingSubscriptionPaymentConditions)[keyof typeof BillingSubscriptionPaymentConditions];

export const Null = { NULL: null } as const;

export type Null = (typeof Null)[keyof typeof Null];

/**
 * Payment method
 * offline means the subscription is not linked to a payment method
 * gocardless_direct-debit means at each new occurrence the client will be automatically debited thanks to GoCardless. To do so, you need a GoCardless account properly configured.
 *
 */
export const BillingSubscriptionPaymentMethod = {
  OFFLINE: 'offline',
  GOCARDLESS_DIRECT_DEBIT: 'gocardless_direct_debit',
  PRO_ACCOUNT_SEPA_CORE: 'pro_account_sepa_core',
} as const;

/**
 * Payment method
 * offline means the subscription is not linked to a payment method
 * gocardless_direct-debit means at each new occurrence the client will be automatically debited thanks to GoCardless. To do so, you need a GoCardless account properly configured.
 *
 */
export type BillingSubscriptionPaymentMethod =
  (typeof BillingSubscriptionPaymentMethod)[keyof typeof BillingSubscriptionPaymentMethod];

export const BillingSubscriptionRuleTypes = {
  WEEKLY: 'weekly',
  MONTHLY: 'monthly',
  YEARLY: 'yearly',
} as const;

export type BillingSubscriptionRuleTypes =
  (typeof BillingSubscriptionRuleTypes)[keyof typeof BillingSubscriptionRuleTypes];

