export const SupplierInvoicePdpDisputeReason = {
  INCORRECT_VAT_RATE: 'incorrect_vat_rate',
  INCORRECT_UNIT_PRICES: 'incorrect_unit_prices',
  INCORRECT_BILLED_QUANTITY: 'incorrect_billed_quantity',
  INCORRECT_BILLED_ITEM: 'incorrect_billed_item',
  DEFECTIVE_DELIVERED_ITEM: 'defective_delivered_item',
  DELIVERY_ISSUE: 'delivery_issue',
  BANK_DETAILS_ERROR: 'bank_details_error',
  INCORRECT_PAYMENT_TERMS: 'incorrect_payment_terms',
  MISSING_LEGAL_NOTICE: 'missing_legal_notice',
  MISSING_CONTRACTUAL_REFERENCE: 'missing_contractual_reference',
  RECIPIENT_ERROR: 'recipient_error',
} as const;

export type SupplierInvoicePdpDisputeReason =
  (typeof SupplierInvoicePdpDisputeReason)[keyof typeof SupplierInvoicePdpDisputeReason];

/**
 * Dispute
 */
export type SupplierInvoicesEInvoiceStatusDisputeRequest = {
  status: 'disputed';
  reason:
    | 'incorrect_vat_rate'
    | 'incorrect_unit_prices'
    | 'incorrect_billed_quantity'
    | 'incorrect_billed_item'
    | 'defective_delivered_item'
    | 'delivery_issue'
    | 'bank_details_error'
    | 'incorrect_payment_terms'
    | 'missing_legal_notice'
    | 'missing_contractual_reference'
    | 'recipient_error';
};

export const SupplierInvoicePdpRefuseReason = {
  INCORRECT_VAT_RATE: 'incorrect_vat_rate',
  CONTRACT_COMPLETED: 'contract_completed',
  DUPLICATE_INVOICE: 'duplicate_invoice',
  RECIPIENT_ERROR: 'recipient_error',
  INCORRECT_PRICES: 'incorrect_prices',
  NON_COMPLIANT_INVOICE: 'non_compliant_invoice',
} as const;

export type SupplierInvoicePdpRefuseReason =
  (typeof SupplierInvoicePdpRefuseReason)[keyof typeof SupplierInvoicePdpRefuseReason];

/**
 * Refuse
 */
export type SupplierInvoicesEInvoiceStatusRefuseRequest = {
  status: 'refused';
  reason:
    | 'incorrect_vat_rate'
    | 'contract_completed'
    | 'duplicate_invoice'
    | 'recipient_error'
    | 'incorrect_prices'
    | 'non_compliant_invoice';
};

/**
 * Undispute
 */
export type SupplierInvoicesEInvoiceStatusUndisputeRequest = {
  status: 'approved';
};

