/**
 * - accepted: quote has been accepted
 * - denied: quote has been denied
 * - expired: quote has expired
 * - invoiced: quote has been invoiced
 * - pending: quote to be denied or accepted
 *
 */
export const EstimateStatus = {
  PENDING: 'pending',
  ACCEPTED: 'accepted',
  DENIED: 'denied',
  INVOICED: 'invoiced',
  EXPIRED: 'expired',
} as const;

/**
 * - accepted: quote has been accepted
 * - denied: quote has been denied
 * - expired: quote has expired
 * - invoiced: quote has been invoiced
 * - pending: quote to be denied or accepted
 *
 */
export type EstimateStatus = (typeof EstimateStatus)[keyof typeof EstimateStatus];

